 @Test public void localChatUsesOwnPanelWithoutCreatingATerminal()throws Exception{WorkspaceStore.Session s=local("Local A");launch(s);assertSame(s,get("selectedLocal"));assertNull(activity.getCurrentSession());assertEquals("",s.handle);assertEquals(View.VISIBLE,((View)get("content")).getVisibility());assertEquals(View.INVISIBLE,activity.getDrawer().getVisibility());assertEquals(View.VISIBLE,((View)get("codexStatus")).getVisibility());assertEquals(R.id.workspace_terminal_tools,((RelativeLayout.LayoutParams)((View)get("content")).getLayoutParams()).getRule(RelativeLayout.BELOW));}
