 @Test public void localLongPressMenuHasChatActionsBeforeSettings()throws Exception{WorkspaceStore.Session s=local("Chat menu");launch(s);Method m=WorkspaceController.class.getDeclaredMethod("sessionMenu",WorkspaceStore.Session.class,boolean.class);m.setAccessible(true);m.invoke(controller,s,true);android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();android.widget.ListAdapter items=dialog.getListView().getAdapter();LocalAiUi ui=(LocalAiUi)get("localAi");java.util.List<String> labels=new java.util.ArrayList<>();for(int n=0;n<items.getCount();n++)labels.add(items.getItem(n).toString());int start=labels.indexOf(ui.tr("Новый чат","New chat"));assertTrue(start>=0);assertEquals(ui.tr("Выбрать чат","Choose chat"),labels.get(start+1));assertEquals(ui.tr("Настройки","Settings"),labels.get(start+2));dialog.dismiss();}
 @Test public void localMessagesUseBlackBackgroundAndInlineSpeakers()throws Exception{WorkspaceStore.Session s=local("Black chat");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);LocalAiUi.Panel.MessageView user=p.message("hello",true),ai=p.message("**answer**",false);assertTrue(user.body.getText().toString().equals("Вы: hello")||user.body.getText().toString().equals("You: hello"));assertEquals("AI: answer\n",ai.body.getText().toString());assertEquals(android.graphics.Color.BLACK,((android.graphics.drawable.ColorDrawable)ai.getBackground()).getColor());assertEquals(android.graphics.Color.BLACK,((android.graphics.drawable.ColorDrawable)user.getBackground()).getColor());assertSame(ai.body,ai.getChildAt(0));}
 @Test public void reasoningOpensIndependentScrollableDialogAndDoesNotExpandChat()throws Exception{WorkspaceStore.Session s=local("Reasoning");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);LocalAiUi.Panel.MessageView row=p.message("<think>long thought\nsecond line</think>Answer",false);assertEquals(2,row.getChildCount());assertEquals(View.VISIBLE,row.toggle.getVisibility());int y=p.historyScroll.getScrollY();row.toggle.performClick();android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing());assertEquals("long thought\nsecond line",row.popupText.getText().toString());assertTrue(row.popupText.getParent() instanceof ScrollView);assertEquals(y,p.historyScroll.getScrollY());dialog.dismiss();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNull(row.popupText);LocalAiUi.Panel.MessageView empty=p.message("<think> </think>answer",false);assertEquals(View.GONE,empty.toggle.getVisibility());}
 @Test public void approvalCardCanOnlyDecideOnceAndRestoredPendingCannotExecute()throws Exception{WorkspaceStore.Session s=local("Approval");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);org.json.JSONObject request=new org.json.JSONObject().put("tool","command").put("command","pwd");java.util.List<Boolean> decisions=new java.util.ArrayList<>();LocalAiUi.Panel.ApprovalCard card=p.new ApprovalCard(request,"pending",decisions::add);card.yes.performClick();card.no.performClick();assertEquals(java.util.Arrays.asList(true),decisions);assertFalse(card.yes.isEnabled());LocalAiUi.Panel.ApprovalCard restored=p.new ApprovalCard(request,"pending",null);assertFalse(restored.yes.isEnabled());assertFalse(restored.no.isEnabled());}
 @Test public void approvalWaitIsCancelledWithoutStartingAnyAction()throws Exception{WorkspaceStore.Session s=local("Cancel approval");s.localChat="approval-cancel-test";launch(s);LocalAiUi localUi=(LocalAiUi)get("localAi");LocalAiUi.Panel p=localUi.existing(s.id);Field worker=LocalAiUi.class.getDeclaredField("worker");worker.setAccessible(true);((java.util.concurrent.ExecutorService)worker.get(localUi)).submit(()->{}).get(3,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();p.cancelled.set(true);java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newSingleThreadExecutor();try{java.util.concurrent.Future<Boolean> result=executor.submit(()->p.awaitApproval(new org.json.JSONObject().put("tool","command").put("command","pwd")));try{result.get(3,java.util.concurrent.TimeUnit.SECONDS);fail();}catch(java.util.concurrent.ExecutionException e){assertTrue(e.getCause() instanceof java.util.concurrent.CancellationException);}assertEquals("interrupted",p.history.getJSONObject(p.history.length()-1).getString("decision"));}finally{executor.shutdownNow();}}
 @Test public void serviceReportsNativeFinishReasonToRemoteClient()throws Exception{android.os.Message[] reply={null};android.os.Messenger messenger=new android.os.Messenger(new android.os.Handler(android.os.Looper.getMainLooper()){public void handleMessage(android.os.Message message){reply[0]=android.os.Message.obtain(message);}});Method send=LocalAiService.class.getDeclaredMethod("send",android.os.Messenger.class,int.class,String.class,String.class,String.class);send.setAccessible(true);send.invoke(null,messenger,7,"done","answer","token_limit");org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotNull(reply[0]);assertEquals("token_limit",reply[0].getData().getString("finish"));assertEquals("answer",reply[0].getData().getString("text"));}
 private CheckBox pathCheck(View v){if(v instanceof CheckBox){String t=((CheckBox)v).getText().toString();if("local-project-only".equals(v.getTag()))return (CheckBox)v;}if(v instanceof android.view.ViewGroup)for(int n=0;n<((android.view.ViewGroup)v).getChildCount();n++){CheckBox result=pathCheck(((android.view.ViewGroup)v).getChildAt(n));if(result!=null)return result;}return null;}
 @Test public void disablingPathChecksRequiresWarningAcceptanceAndCanBeCancelledRepeatedly()throws Exception{LocalAiUi ui=(LocalAiUi)get("localAi");LocalAiUi.Selection selection=new LocalAiUi.Selection(new WorkspaceStore.Session());CheckBox check=pathCheck(ui.settings(selection,()->{}));assertNotNull(check);check.setChecked(false);android.app.AlertDialog warning=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(warning.isShowing());assertTrue(check.isChecked());assertTrue(selection.checkPaths);warning.getButton(-2).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(selection.checkPaths);check.setChecked(false);warning=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();warning.getButton(-1).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(check.isChecked());assertFalse(selection.checkPaths);check.setChecked(true);assertTrue(selection.checkPaths);check.setChecked(false);warning=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();warning.dismiss();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(check.isChecked());assertTrue(selection.checkPaths);}

 @Test public void activityIndicatorUpdatesWithoutRebuildingMessages()throws Exception{WorkspaceStore.Session s=local("Indicator");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);View message=p.message("keep",true);p.messages.addView(message);p.busy=true;p.updateLabel();assertEquals(View.VISIBLE,p.activityDots.getVisibility());assertSame(get("codexStatus"),p.activityDots.getParent());assertSame(message,p.messages.getChildAt(0));assertEquals(View.GONE,p.status.getVisibility());p.busy=false;p.updateLabel();assertEquals(View.INVISIBLE,p.activityDots.getVisibility());assertSame(message,p.messages.getChildAt(0));}
