 @Test public void toolHistoryPairsResultsWithoutLosingLegacyOutput()throws Exception{WorkspaceStore.Session s=local("History cards");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);org.json.JSONObject request=new org.json.JSONObject().put("tool","list").put("path",".");p.history=new org.json.JSONArray().put(new org.json.JSONObject().put("role","assistant").put("text",request.toString()).put("toolRequest",request).put("toolState","done").put("toolOutput","exit=0\nfile")).put(new org.json.JSONObject().put("role","user").put("text","exit=0\nfile").put("toolResult","list"));p.drawHistory();assertEquals(1,p.messages.getChildCount());assertTrue(p.messages.getChildAt(0) instanceof LocalAiUi.ToolCard);p.history=new org.json.JSONArray().put(new org.json.JSONObject().put("role","user").put("text","legacy result").put("toolResult","list"));p.drawHistory();assertEquals("legacy result",((LocalAiUi.ToolCard)p.messages.getChildAt(0)).result);}
 @Test public void malformedHistoricalRequestDoesNotHideFollowingMessages()throws Exception{WorkspaceStore.Session s=local("Malformed history");launch(s);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(s.id);p.history=new org.json.JSONArray().put(new org.json.JSONObject().put("role","assistant").put("text","{\"tool\":\"read\"}")).put(new org.json.JSONObject().put("role","user").put("text","still visible"));p.drawHistory();assertEquals(2,p.messages.getChildCount());}

 private EditText sessionName(View view){if(view instanceof EditText&&("Название сессии".contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||"Session name".contentEquals(view.getContentDescription()==null?"":view.getContentDescription())))return (EditText)view;if(view instanceof android.view.ViewGroup)for(int n=0;n<((android.view.ViewGroup)view).getChildCount();n++){EditText result=sessionName(((android.view.ViewGroup)view).getChildAt(n));if(result!=null)return result;}return null;}
