 @Test public void activePermissionChangesKeepLoadedModelAndHistory()throws Exception{WorkspaceStore.Session s=local("Permissions");launch(s);LocalAiUi ui=(LocalAiUi)get("localAi");LocalAiUi.Panel p=ui.existing(s.id);settleLocal(p);p.loaded=true;s.localAccess="chat";org.json.JSONArray history=p.history;LocalAiUi.Selection next=new LocalAiUi.Selection(s);next.access="write";next.checkPaths=false;next.confirmActions=true;next.project="/sdcard/Download";p.applySettings("Permissions",next);assertTrue(p.loaded);assertSame(history,p.history);assertEquals("write",s.localAccess);assertFalse(s.localCheckPaths);assertTrue(s.localConfirmActions);assertTrue(LocalAiTools.instructions(s.copy()).contains("/sdcard/Download"));next.access="read";p.applySettings("Permissions",next);try{LocalAiTools.authorize(s.copy(),new org.json.JSONObject().put("tool","write").put("path","note").put("text","x"));fail();}catch(SecurityException expected){}p.loaded=false;}
 @Test public void streamingUpdatesKeepInputEditableInSameAndOtherLocalSession()throws Exception{WorkspaceStore.Session a=local("A"),b=local("B");lifecycle.visible();launch(a);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(a.id);settleLocal(p);LocalAiUi.Panel.MessageView answer=p.message("",false);p.messages.addView(answer);EditText input=(EditText)get("terminalInput");input.requestFocus();input.setText("same draft");p.busy=true;for(int n=0;n<4;n++)p.updateAnswer(answer,"token "+n);assertTrue(p.root.isShown());assertTrue(answer.body.getText().toString().contains("token 3"));assertTrue(input.hasFocus());assertEquals("same draft",input.getText().toString());input.append(" text");assertEquals("same draft text",input.getText().toString());launch(b);input.requestFocus();input.setText("other draft");for(int n=0;n<4;n++)p.updateAnswer(answer,"background "+n);p.drawHistory();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(input.hasFocus());assertEquals("other draft",input.getText().toString());input.append(" works");assertEquals("other draft works",input.getText().toString());p.busy=false;}
