 @Test public void answeredApprovalsCollapseIntoPillsWithoutReplayingDecision()throws Exception{
  WorkspaceStore.Session profile=local("Approval pill");launch(profile);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(profile.id);settleLocal(p);JSONObject request=new JSONObject().put("tool","command").put("command","pwd");java.util.List<Boolean> decisions=new java.util.ArrayList<>();
  for(boolean allow:new boolean[]{true,false}){LocalAiUi.Panel.ApprovalCard card=p.new ApprovalCard(request,"pending",decisions::add);assertEquals(View.VISIBLE,card.expanded.getVisibility());assertEquals(View.GONE,card.state.getVisibility());(allow?card.yes:card.no).performClick();assertEquals(View.GONE,card.expanded.getVisibility());assertEquals(View.VISIBLE,card.state.getVisibility());assertTrue(card.state.getText().toString().contains(allow?"выдано":"отклонено")||card.state.getText().toString().contains(allow?"granted":"denied"));assertEquals(-2,card.getLayoutParams().width);assertFalse(card.yes.isEnabled());assertFalse(card.no.isEnabled());card.state.performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(d.isShowing());d.dismiss();}
  assertEquals(java.util.Arrays.asList(true,false),decisions);LocalAiUi.Panel.ApprovalCard restored=p.new ApprovalCard(request,"accepted",null);assertEquals(View.GONE,restored.expanded.getVisibility());restored.yes.performClick();assertEquals(2,decisions.size());LocalAiUi.Panel.ApprovalCard interrupted=p.new ApprovalCard(request,"pending",null);assertTrue(interrupted.state.getText().toString().contains("прерван")||interrupted.state.getText().toString().contains("interrupted"));
 }
 @Test public void approvalBetweenActionAndResultDoesNotCreateFalseNotExecutedCard()throws Exception{
  WorkspaceStore.Session profile=local("Approval result");launch(profile);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(profile.id);settleLocal(p);JSONObject request=new JSONObject().put("tool","write").put("path","/test").put("text","hello");
  p.history=new org.json.JSONArray().put(new JSONObject().put("role","assistant").put("text",request.toString()).put("toolRequest",request).put("toolState","done").put("toolOutput","exit=0\nSAVED")).put(new JSONObject().put("role","assistant").put("approval",request).put("decision","accepted")).put(new JSONObject().put("role","assistant").put("contextEvent",true).put("text","notice")).put(new JSONObject().put("role","user").put("toolResult","write").put("text","exit=0\nSAVED"));
  assertTrue(LocalAiUi.recordedToolResult(p.history,3));p.drawHistory();int cards=0;for(int i=0;i<p.messages.getChildCount();i++)if(p.messages.getChildAt(i) instanceof LocalAiUi.ToolCard){cards++;assertTrue(((LocalAiUi.ToolCard)p.messages.getChildAt(i)).title.getText().toString().contains("Готово")||((LocalAiUi.ToolCard)p.messages.getChildAt(i)).title.getText().toString().contains("Done"));}assertEquals(1,cards);
  p.history.getJSONObject(3).put("text","different output");assertFalse(LocalAiUi.recordedToolResult(p.history,3));p.history.getJSONObject(2).remove("contextEvent");p.history.getJSONObject(2).put("role","user").put("text","new request");assertFalse(LocalAiUi.recordedToolResult(p.history,3));
 }
 @Test public void approvalActuallyWaitsForClickBeforeReturningPermission()throws Exception{
  WorkspaceStore.Session profile=local("Wait approval");profile.localChat="wait-approval-fixture";launch(profile);LocalAiUi.Panel p=((LocalAiUi)get("localAi")).existing(profile.id);settleLocal(p);java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newSingleThreadExecutor();
  try{java.util.concurrent.Future<Boolean> result=executor.submit(()->p.awaitApproval(new JSONObject().put("tool","command").put("command","pwd")));LocalAiUi.Panel.ApprovalCard card=null;long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(3);
   while(card==null&&System.nanoTime()<until){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();for(int i=0;i<p.messages.getChildCount();i++)if(p.messages.getChildAt(i) instanceof LocalAiUi.Panel.ApprovalCard)card=(LocalAiUi.Panel.ApprovalCard)p.messages.getChildAt(i);if(card==null)Thread.sleep(5);}
   assertNotNull(card);assertFalse(result.isDone());assertEquals("pending",p.history.getJSONObject(p.history.length()-1).getString("decision"));card.yes.performClick();assertTrue(result.get(3,java.util.concurrent.TimeUnit.SECONDS));org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals("accepted",p.history.getJSONObject(p.history.length()-1).getString("decision"));assertEquals(View.GONE,card.expanded.getVisibility());
  }finally{p.cancelled.set(true);executor.shutdownNow();}
 }
